"""Category 2 top-up: 46 more authored fact sheets (definition, mechanism, example, misconception)."""
from lib import *

CAT = "general_knowledge"
R = seeded("knowledge2")
out = []
T = []


def t(area, topic, d, m, e, c):
    T.append((area, topic, d, m, e, c))


t("science", "cellular respiration", "Cellular respiration is the process by which cells break down sugar to release energy in a usable form called ATP.", "In the presence of oxygen, glucose is broken down through glycolysis, the Krebs cycle and the electron transport chain in the mitochondria, producing carbon dioxide and water.", "Your muscle cells use respiration to turn the food you ate into the energy that powers a run.", "Respiration is not the same as breathing; breathing brings oxygen in, while respiration happens inside each cell.")
t("science", "osmosis", "Osmosis is the movement of water across a semipermeable membrane from a region of lower solute concentration to a region of higher solute concentration.", "Water moves until the concentrations balance or pressure stops the flow, which is why cells swell in pure water and shrink in salty water.", "Soaking raisins in water makes them plump because water flows into them.", "In osmosis it is the water that moves, not the dissolved particles, which can't cross the membrane.")
t("science", "the Doppler effect", "The Doppler effect is the change in the observed frequency of a wave when the source and the observer move relative to each other.", "Waves bunch up in front of a moving source and stretch out behind it, so approaching sources sound higher and receding ones lower.", "An ambulance siren sounds higher as it approaches and lower as it drives away.", "The source doesn't actually change its pitch; the change is in what the observer receives.")
t("science", "refraction", "Refraction is the bending of light as it passes from one transparent medium into another.", "Light changes speed when entering a different material, and the change of speed at an angle makes the path bend.", "A straw looks bent when it is partly in a glass of water.", "Refraction is not a trick of the eye; it is a physical change in the direction of the light.")
t("science", "the ozone layer", "The ozone layer is a region of the stratosphere with a high concentration of ozone that absorbs most of the Sun's harmful ultraviolet-B and ultraviolet-C radiation.", "Ozone forms when UV light splits oxygen molecules, and certain chemicals such as CFCs can destroy it.", "The Montreal Protocol of 1987 phased out ozone-depleting chemicals, and the layer has been slowly recovering.", "The ozone hole is a different issue from global warming, although both involve the atmosphere.")
t("science", "supernovas", "A supernova is the explosion of a star at the end of its life, briefly outshining an entire galaxy.", "It can happen when a massive star's core collapses or when a white dwarf in a binary system accumulates too much mass.", "The elements heavier than iron, such as gold, were largely forged in extreme events like these and neutron-star collisions.", "A supernova is not the Sun's fate; the Sun is too small and will become a white dwarf instead.")
t("science", "genetic mutations", "A mutation is a change in the DNA sequence of an organism.", "Mutations arise from copying errors or damage and can be harmless, harmful or occasionally beneficial.", "A mutation in a single base can change one amino acid in a protein, as in sickle cell disease.", "Most mutations are neutral, and mutation is not the same as a superpower or a deliberate adaptation.")
t("science", "homeostasis", "Homeostasis is the ability of a living system to keep its internal conditions stable despite changes outside.", "Sensors detect a change, a control centre compares it with a set point, and effectors act to correct it through negative feedback.", "When you get hot, you sweat, and the evaporation cools your body back toward 37 °C.", "Homeostasis doesn't mean nothing changes; values fluctuate around a set point.")
t("science", "the nitrogen cycle", "The nitrogen cycle is the series of processes that move nitrogen between the air, soil and living things.", "Bacteria convert atmospheric nitrogen into forms plants can use, animals get it by eating plants, and other bacteria return it to the air.", "Legumes such as peas host bacteria in their roots that fix nitrogen, which is why farmers rotate them with other crops.", "Although the air is about 78% nitrogen, most organisms can't use it directly in that form.")
t("science", "fossils", "Fossils are preserved remains or traces of ancient organisms, usually found in sedimentary rock.", "Hard parts like bones and shells are replaced or encased by minerals over millions of years, and layers of rock help date them.", "Trilobite fossils help geologists recognise rocks from the Paleozoic era.", "Fossilisation is rare; only a tiny fraction of organisms ever become fossils.")
t("science", "static electricity", "Static electricity is an imbalance of electric charge on the surface of objects.", "Rubbing two materials together can transfer electrons from one to the other, leaving one positive and the other negative until the charge discharges.", "A balloon rubbed on hair can stick to a wall.", "Static electricity doesn't need a spark to exist; the spark or shock is just the discharge when the charge finds a path.")
t("science", "thermal expansion", "Thermal expansion is the tendency of matter to change in size when its temperature changes.", "Heating makes particles move more, so most solids, liquids and gases take up more space.", "Bridges have expansion joints to allow the steel to lengthen on hot days.", "Water is unusual: it expands when it freezes, which is why ice floats and pipes can burst.")
t("technology", "search engines", "A search engine is a system that finds and ranks web pages in response to a query.", "It crawls the web, builds an index of content, and ranks results using signals such as relevance, quality and links.", "Typing a question into a search box returns a ranked list of pages in a fraction of a second.", "Search engines don't search the live web at the moment you type; they search their index, which can be out of date.")
t("technology", "QR codes", "A QR code is a two-dimensional barcode that stores data such as a web address in a pattern of black and white squares.", "A camera reads the pattern, and built-in error correction lets it work even when partly damaged.", "Scanning a code on a poster can open a website on your phone.", "A QR code is just a way to encode text; it can lead to a malicious link, so check where it goes.")
t("technology", "load balancers", "A load balancer distributes incoming requests across several servers.", "It uses strategies like round-robin or least connections and can stop sending traffic to servers that fail health checks.", "A busy website puts a load balancer in front of many application servers.", "A load balancer doesn't make slow code fast; it spreads work, but the underlying application still needs to perform.")
t("technology", "caching", "Caching stores copies of data in a faster place so it can be reused instead of recomputed or refetched.", "Caches exist at many levels: CPU, browser, CDN and application, and they must be invalidated or expire when data changes.", "A browser keeps your site's logo file so it doesn't download it again for every page.", "The hard part isn't storing the data but knowing when it is stale.")
t("technology", "software bugs", "A software bug is a flaw in a program that causes it to behave incorrectly or unexpectedly.", "Bugs come from mistaken logic, misunderstood requirements, unexpected inputs or interactions between components.", "A calculator app that rounds a result incorrectly has a bug.", "Bugs aren't always visible; some quietly produce wrong results, which is why tests matter.")
t("technology", "digital signatures", "A digital signature is a cryptographic proof that a message came from a particular sender and wasn't altered.", "The sender signs a hash of the message with a private key, and anyone can check it with the matching public key.", "Software updates are signed so your computer can confirm they come from the publisher.", "A signature doesn't hide the content; it proves authenticity and integrity, not secrecy.")
t("technology", "data compression", "Data compression reduces the amount of data needed to store or send information.", "Lossless methods such as ZIP rebuild the original exactly, while lossy methods like JPEG and MP3 discard details people are unlikely to notice.", "A zipped folder is smaller than the original files but restores them perfectly.", "Compressing something twice rarely helps, because well-compressed data looks random and has little left to remove.")
t("technology", "virtual machines", "A virtual machine is a software-based computer that runs inside another computer.", "A hypervisor shares the physical hardware between several isolated virtual machines, each with its own operating system.", "A developer can run a Linux virtual machine on a Windows laptop for testing.", "A virtual machine is not the same as a container; containers share the host's kernel and are lighter.")
t("history", "the Byzantine Empire", "The Byzantine Empire was the continuation of the Roman Empire in the east, centred on Constantinople, lasting until 1453.", "It preserved Roman law, Greek learning and Orthodox Christianity, and acted as a bridge between Europe and Asia.", "The Hagia Sophia in Constantinople was built under Emperor Justinian in the sixth century.", "'Byzantine' is a later name; its people called themselves Romans.")
t("history", "the Age of Exploration", "The Age of Exploration (roughly the 15th to 17th centuries) was a period when European powers sailed across the oceans to find new trade routes and territories.", "Advances in ships, navigation and mapmaking, along with the search for spices and wealth, drove voyages by Portugal, Spain and later others.", "Vasco da Gama reached India by sea in 1498, and Columbus reached the Americas in 1492.", "These lands were not empty; they were home to long-established societies, and exploration led to conquest and devastating disease.")
t("history", "the Protestant Reformation", "The Reformation was a 16th-century religious movement that challenged the authority and practices of the Catholic Church and led to new Protestant churches.", "Martin Luther's 95 Theses in 1517 sparked debate, and the printing press spread the ideas quickly.", "Luther translated the Bible into German so ordinary people could read it.", "The Reformation wasn't just theology; politics, power and printing were all important.")
t("history", "the Russian Revolution", "The Russian Revolution of 1917 overthrew the tsar and, after a second upheaval, brought the Bolsheviks to power.", "War, hunger and political unrest weakened the monarchy, and Lenin's party seized power in October, leading to a civil war and the Soviet Union.", "Tsar Nicholas II abdicated in March 1917.", "There were two revolutions in 1917, not one, and the outcome was far from certain at the time.")
t("history", "the Great Depression", "The Great Depression was a severe worldwide economic downturn that began in 1929 and lasted through the 1930s.", "A stock market crash, bank failures and falling demand led to mass unemployment in many countries.", "In the United States, unemployment reached roughly a quarter of the workforce at its peak.", "The 1929 crash was a trigger, not the only cause; weak banks and falling demand played big roles.")
t("history", "decolonisation", "Decolonisation was the process by which colonies gained independence from European powers, mostly after World War II.", "Nationalist movements, weakened empires and international pressure led to dozens of new states in Asia and Africa between the 1940s and 1970s.", "India in 1947 and Ghana in 1957 were among the earliest.", "Independence didn't end all colonial influence; borders, economies and institutions often reflected the colonial past.")
t("history", "the Viking Age", "The Viking Age (about 793 to 1066) was a period when Scandinavian seafarers raided, traded and settled across Europe and beyond.", "Their longships could cross oceans and navigate shallow rivers, which let them reach Britain, Iceland, Greenland and even North America.", "Leif Erikson is credited with reaching North America around the year 1000.", "Vikings were also traders, farmers and settlers, and the horned helmet is a later invention.")
t("geography", "the Great Barrier Reef", "The Great Barrier Reef is the world's largest coral reef system, off the coast of Queensland, Australia.", "It comprises thousands of individual reefs and islands and is visible from space.", "It supports a huge variety of fish, turtles and corals.", "It is not a single reef but a system, and it faces threats from warming waters and bleaching.")
t("geography", "the Alps", "The Alps are a mountain range that stretches across eight countries in Central Europe.", "They were uplifted by the collision of the African and Eurasian plates, and glaciers carved their valleys.", "Mont Blanc is the highest peak at about 4,800 metres.", "Alpine glaciers have been shrinking steadily with warming temperatures.")
t("geography", "the Mediterranean Sea", "The Mediterranean is a sea almost enclosed by Europe, Africa and Asia, connected to the Atlantic by the Strait of Gibraltar.", "It has a warm, dry-summer climate along its coasts and a long history as a crossroads of trade and cultures.", "Ancient Greece, Rome and Egypt all grew around its shores.", "It's small compared with the great oceans, and it has very little tidal movement.")
t("geography", "tundra", "Tundra is a cold, treeless biome with low-growing plants and frozen ground.", "In arctic tundra, a layer of permanently frozen soil called permafrost lies beneath the surface, limiting tree roots.", "Reindeer, lemmings and Arctic foxes live in the tundra.", "Tundra isn't a barren wasteland; it has rich life in a short, intense summer.")
t("economics", "supply chains", "A supply chain is the network of people, companies and activities that gets a product from raw materials to the customer.", "It involves sourcing, manufacturing, transport and retail, and delays at any step can ripple through the rest.", "A smartphone uses parts from factories in many countries.", "Efficient is not always resilient; chains optimised for low cost can break when a link fails.")
t("economics", "tariffs", "A tariff is a tax on imported goods.", "It raises the price of foreign goods, which can protect domestic producers but also raise prices for consumers and invite retaliation.", "A country might put a tariff on imported steel to support its own steel industry.", "Tariffs are paid by importers, who often pass the cost on to buyers, not by the exporting country directly.")
t("economics", "government budget deficits", "A budget deficit occurs when a government spends more than it collects in revenue in a given year.", "It borrows to cover the gap, which adds to the national debt over time.", "A government that spends 110 and collects 100 has a deficit of 10.", "A deficit and the debt are different: the deficit is a yearly gap, and the debt is the accumulated total.")
t("economics", "microfinance", "Microfinance provides small loans and financial services to people who can't access traditional banking.", "Lenders often use group lending and local knowledge in place of collateral.", "A small loan can help a street vendor buy more stock.", "Microfinance isn't a cure-all; results depend on interest rates, the borrowers' circumstances and how the loans are structured.")
t("economics", "subsidies", "A subsidy is financial support from the government to a person, firm or industry to encourage an activity.", "It can lower prices or boost production, but it costs taxpayers and can distort markets.", "Many countries subsidise renewable energy installations.", "Subsidies aren't automatically good or bad; their value depends on what they achieve and what they cost.")
t("economics", "economies of scale", "Economies of scale are cost advantages a business gets as it produces more.", "Fixed costs are spread over more units, and bulk buying and specialisation can reduce the cost per unit.", "A large bakery makes each loaf more cheaply than a tiny one.", "Scale can reverse: very large organisations can suffer from complexity and slow decisions.")
t("arts", "the Baroque", "The Baroque was a style of art, architecture and music in the 17th and early 18th centuries, known for drama, ornament and contrast.", "Artists used strong light and shadow, movement and rich detail to create emotion and grandeur.", "Bach and Vivaldi composed in the Baroque period, and Caravaggio painted with its dramatic lighting.", "Baroque doesn't mean simply 'old-fashioned'; it is a specific style with its own features.")
t("arts", "iambic pentameter", "Iambic pentameter is a line of verse with five pairs of syllables, each pair an unstressed then a stressed syllable.", "The pattern da-DUM repeated five times gives a rhythm close to natural speech.", "'Shall I compare thee to a summer's day?' is in iambic pentameter.", "Real verse bends the pattern often, because variation keeps the rhythm from sounding mechanical.")
t("arts", "perspective in painting", "Linear perspective is a technique for creating the illusion of depth on a flat surface.", "Parallel lines appear to converge at a vanishing point on the horizon, and objects shrink with distance.", "Renaissance artists such as Brunelleschi and Alberti developed it systematically.", "Perspective is a convention; many cultures used other ways to show space and depth.")
t("arts", "the unreliable narrator", "An unreliable narrator is a storyteller whose account can't be fully trusted.", "They may be biased, mistaken, lying or limited in knowledge, which forces readers to question what is true.", "In 'The Great Gatsby', Nick Carraway's view of events is colored by his own judgements.", "An unreliable narrator isn't necessarily a liar; sometimes they simply don't understand what they're seeing.")
t("everyday", "washing hands properly", "Proper hand washing means scrubbing with soap and water for about 20 seconds.", "Soap breaks apart oils that hold germs, and rubbing and rinsing remove them.", "Wash before eating or cooking and after using the toilet or coughing.", "Hot water isn't necessary for effective cleaning; the soap and the time spent matter more.")
t("everyday", "composting", "Composting is the controlled breakdown of organic waste into a nutrient-rich soil improver.", "Microbes feed on a balance of 'greens' such as food scraps and 'browns' such as dry leaves, helped by air and moisture.", "A small bin in the garden can turn kitchen scraps into compost within months.", "A healthy compost pile shouldn't smell bad; a sour smell usually means too much wet material or too little air.")
t("everyday", "your carbon footprint", "A carbon footprint is the total greenhouse gas emissions caused by a person, product or activity.", "It includes direct emissions, such as driving, and indirect ones, such as the electricity and the manufacture of goods you buy.", "Flying, heating and diet are among the largest parts of many people's footprints.", "Small actions help, but big sources like transport, home energy and food tend to matter most.")
t("everyday", "meal prepping", "Meal prepping means preparing food or components ahead of time for use during the week.", "Cooking in batches and storing portions saves time and reduces the temptation to buy takeaway.", "Roasting a tray of vegetables and cooking a pot of rice on Sunday gives you the base for several lunches.", "Prepped food has a limited fridge life, so most cooked meals should be eaten within three or four days.")
t("everyday", "stretching", "Stretching is the practice of lengthening muscles to improve flexibility and comfort.", "Gentle static stretches held for 20 to 30 seconds are common after exercise, while dynamic movements suit warm-ups.", "Reaching for your toes after a walk stretches the hamstrings.", "Stretching a cold muscle hard isn't a good idea; warm up a little first, and never stretch into sharp pain.")
t("everyday", "reading a lease", "A lease is a contract setting the terms for renting a property.", "It covers the rent, duration, deposit, repairs, notice periods and what happens if either side breaks the terms.", "Check who pays for utilities, how the deposit is protected and how to end the lease early.", "Verbal promises from a landlord don't replace what the written lease says, so get changes in writing.")
t("everyday", "tipping etiquette", "Tipping practices vary widely by country and by service.", "In some places a tip is expected and part of wages, in others service is included and tips are optional.", "In the United States a 15 to 20 percent tip in restaurants is customary, whereas in Japan it is generally not expected.", "A rule that works in one country can offend or confuse in another, so check local norms.")

for area, topic, d, m, e, c in T:
    qw = R.choice(["What is {t}?", "Can you explain {t}?", "Tell me about {t}.", "I keep hearing about {t}. What is it?"]).format(t=topic)
    qe = R.choice(["Give me an example of {t}.", "Can you give a real-world example involving {t}?"]).format(t=topic)
    qm = R.choice(["What's a common misunderstanding about {t}?", "What do people often get wrong about {t}?"]).format(t=topic)
    qb = R.choice(["In one sentence, what is {t}?", "Quick definition of {t}?"]).format(t=topic)
    out.append(mk(CAT, "knowledge_" + area, [("user", qw), ("assistant", f"{d} {m}")], "k2_" + topic, "easy", "authored", pick(R, SYS_GENERAL)))
    out.append(mk(CAT, "knowledge_" + area, [("user", qe), ("assistant", f"{e} {m.split('. ')[0].rstrip('.')}.")], "k2_" + topic, "easy", "authored", pick(R, SYS_GENERAL)))
    out.append(mk(CAT, "knowledge_" + area, [("user", qm), ("assistant", c)], "k2_" + topic, "medium", "authored", pick(R, SYS_GENERAL)))
    out.append(mk(CAT, "knowledge_" + area, [("user", qb), ("assistant", d)], "k2_" + topic, "easy", "authored", pick(R, SYS_GENERAL)))

print("topics:", len(T))
save("knowledge2", out)
